<script setup lang="ts">
import type { RequestLogView } from '#shared/types'
interface LogDetail extends RequestLogView { requestBody: unknown; responseBody: unknown; sessionId: string | null }
useHead({ title: '请求详情 · Command Code Manager' })
const route = useRoute()
const { data, pending, error, refresh } = await useFetch<LogDetail>(() => '/api/logs/' + encodeURIComponent(String(route.params.id)))
useLiveRefresh(refresh)
</script>
<template>
  <NuxtLink to="/logs" class="back-link"><UIcon name="i-ph-arrow-left-bold" />返回请求日志</NuxtLink><AppPageHeader title="请求详情" :description="data ? formatDate(data.createdAt) + ' · ' + data.protocol : '查看本次请求的实际记录。'"><button class="button" :disabled="pending" @click="refresh()"><UIcon name="i-ph-arrow-clockwise-bold" :class="{ spinning: pending }" />刷新详情</button></AppPageHeader><AppState v-if="error" :error="error" @retry="refresh()" /><AppState v-else-if="!data" :loading="pending" /><template v-else><section class="panel log-summary"><div><span>调用结果</span><StatusBadge :status="data.status" /></div><div><span>模型</span><strong class="mono">{{ data.model || '未指定' }}</strong></div><div><span>账号</span><NuxtLink v-if="data.accountId" :to="'/accounts/' + data.accountId" class="text-link">{{ data.accountLabel || '查看账号' }}</NuxtLink><strong v-else>未分配 / 已删除</strong></div><div><span>访问密钥</span><strong>{{ data.keyName || '记录不可用' }}</strong></div><div><span>耗时 / HTTP</span><strong>{{ formatDuration(data.durationMs) }} · {{ data.httpStatus ?? '未知' }}</strong></div><div><span>输出方式</span><strong>{{ data.streaming ? '流式输出' : '非流式输出' }}</strong></div></section><div v-if="data.errorMessage" class="notice error-notice" role="alert"><UIcon name="i-ph-warning-circle-bold" /><div><strong>调用错误</strong><p>{{ data.errorMessage }}</p></div></div><div v-if="data.responseTruncated" class="notice warning-notice"><UIcon name="i-ph-warning-bold" /><p>此条回复超过日志保存上限，保存内容已截断。下方不是完整回复。</p></div><div class="log-bodies"><JsonViewer :value="data.requestBody" title="请求内容" empty-text="未保存请求内容" /><JsonViewer :value="data.responseBody" title="回复内容" empty-text="未保存回复内容；请求可能尚未产生回复或在此前失败" /></div><section class="panel section-gap"><div class="panel-heading"><h2>实际用量</h2></div><RawFields :value="data.usage" /></section><dl class="log-identifiers"><div><dt>请求 ID</dt><dd class="mono">{{ data.id }}</dd></div><div><dt>会话 ID</dt><dd class="mono">{{ data.sessionId || '未提供 / 未识别' }}</dd></div></dl></template>
</template>
